We assume, without of loss of generality, that $N\in\mathbb{N}$ is large.
Let $B_h=q_{j_1, s_{j_1}}\cdot\ldots\cdot q_{j_m,
  s_{j_m}}\cdot Q_0\le e^{N^{\rho}}$
and observe that according to the notation from \eqref{eq:25} and \eqref{eq:13},  we
have
\begin{multline}
  \label{eq:136}
  \big\|\mathcal S_{M, M}^{\sigma}\big(f_u:u\in\mathcal
  U_{\mathbb{N}_k}\big)\big\|_{\ell^{2r}}^{2r}=
\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\sum_{v\in\mathcal V_{M}^{\sigma}}f_{w+v}(x)\Big|^2\bigg)^r\\
\le\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\Big|\mathcal{F}^{-1}\Big(\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\Theta(\xi-b/Q_0-v-w)\eta_N(\xi-b/Q_0-v-w)\hat{f}(\xi)\Big)(x)\Big|^2\bigg)^r\\
=\sum_{n\in \mathbb{N}_{B_h}^d}\sum_{x\in\mathbb{Z}^d}\bigg(\sum_{w\in\mathcal
  U_{M^c}}\big|\mathcal{F}^{-1}\big(\Theta\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big|^2\bigg)^r
\end{multline}
where 
\begin{align}
  \label{eq:137}
  G(\xi; n, w)=\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}^d}\hat{f}(\xi+b/Q_0+v+w)e^{-2\pi i
(b/Q_0+v)\cdot n}.
\end{align}

We  know that for each $0<p<\infty$ there is a constant $C_p>0$ such
that for any $d\in\mathbb{N}$ and $\lambda_1,\ldots,\lambda_d\in\mathbb{C}^d$ we have
\begin{align}
  \label{eq:1411}
  \bigg(\int_{\mathbb{C}^d}|\lambda_1z_1+\ldots+\lambda_dz_d|^pe^{-\pi
  |z|^2} {\rm d} z\bigg)^{1/p}=C_p\big(|\lambda_1|^2+\ldots+|\lambda_d|^2\big)^{1/2}.
\end{align}

By Proposition 4.5 from \cite{mst1}, with the sequence of multipliers
$\Theta_N=\Theta$ for all $N\in\mathbb{N}$ and $\Theta$ as in \eqref{eq:155},   we have 
\begin{align}
\label{eq:140}
\big\|\mathcal{F}^{-1}\big(\Theta\eta_N G(\: \cdot\: ;n,
w)\big)(B_hx+n)\big\|_{\ell^{2r}(x)}\le C_{\rho, r}\mathbf A_{2r}
\big\|\mathcal{F}^{-1}\big(\eta_N G(\: \cdot\: ;n, w)\big)(B_hx+n)\big\|_{\ell^{2r}(x)}
\end{align}
since $\inf_{\gamma\in\Gamma}\varepsilon_{\gamma}^{-1}\ge
e^{N^{2\rho}}\ge 2e^{(d+1)N^{\rho}}\ge B_h$ for sufficiently large
$N\in\mathbb{N}$. 

Therefore, combining \eqref{eq:140} with \eqref{eq:1411} we obtain that
\begin{multline}
  \label{eq:142}
