  F^{-1}\Big(\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-u)\hat{f}(\xi)\Big):u\in\mathcal
  U_{\mathbb{N}_k}\Big)\Big\|_{\ell^{2r}}^{2r}\le C_{\rho, r}^{2r}\|f\|_{\ell^{2r}}.
\end{align}
Since there are $2^k$ possible choices of sets $M\subseteq \mathbb{N}_k$ and $k\in\mathbb{N}_D$
then \eqref{eq:134} will follow and the proof of Theorem \ref{thm:500}
will be completed. If $r=1$ the then Plancherel's theorem does the job
since the  functions $\eta_N(\xi-b/Q_0-v-w)$ are disjointly supported 
for all $b/Q_0\in \mathbb{N}_{Q_0}$, $w\in\mathcal
  U_{M^c}$, $v\in\mathcal V_{M}^{\sigma}$ and $\sigma=(s_{j_1},\ldots,
s_{j_m})\in\mathbb{N}_{\beta_{j_1}}\times\ldots\times\mathbb{N}_{\beta_{j_m}}$. For
general $r\ge2$, since $\|f\|_{\ell^{2r}}^{2r}=\|f\|_{\ell^{2}}^2$
because we have assumed that $f$ is a characteristic function of a
finite set in $\mathbb{Z}^d$, it
suffices to prove for any $x\in\mathbb{Z}^d$ that
\begin{align}
  \label{eq:139}
  \sum_{w\in\mathcal
  U_{M^c}}\Big|\mathcal{F}^{-1}\Big(\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\hat{f}(\xi)\Big)(x)\Big|^2\le
C_{\rho, r}.
\end{align}
In fact, since $\|f\|_{\ell^{\infty}}=1$, it is enough to show 
\begin{align}
  \label{eq:144}
  \Big\|\mathcal{F}^{-1}\Big(\sum_{w\in\mathcal
  U_{M^c}}\alpha(w)\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\Big)\Big\|_{\ell^1}\le
C_{\rho, r}
\end{align}
for any sequence of complex numbers $\big(\alpha(w):  w\in\mathcal
  U_{M^c}\big)$ such that
  \begin{align}
    \label{eq:50}
    \sum_{w\in\mathcal
  U_{M^c}}|\alpha(w)|^2=1.
  \end{align}
Computing the Fourier transform we obtain 
\begin{multline}
  \label{eq:145}
  \mathcal{F}^{-1}\Big(\sum_{w\in\mathcal
    U_{M^c}}\alpha(w)\sum_{v\in\mathcal V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}\eta_N(\xi-b/Q_0-v-w)\Big)\\
  =\Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i x\cdot
    w}\Big)\cdot \det(\mathcal E_N)\mathcal
  F^{-1}\eta\big(\mathcal E_Nx\big)\cdot\Big(\sum_{v\in\mathcal
    V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}e^{-2\pi i
    x\cdot (b/Q_0+v)}\Big).
\end{multline}
The function 
\begin{align}
  \label{eq:146}
  \sum_{v\in\mathcal
    V_{M}^{\sigma}}\sum_{b\in\mathbb{N}_{Q_0}}e^{-2\pi i
    x\cdot (b/Q_0+v)}
\end{align}
 can be written as a sum of $2^m$ functions 
\begin{align}
  \label{eq:147}
  \sum_{b\in\mathbb{N}_{Q}}e^{-2\pi i
    x\cdot (b/Q)} =
\begin{cases} 
Q^d & \mbox{if } x \equiv 0 \pmod{Q}, \\
0   & \mbox{otherwise,} 
\end{cases}  
\end{align}
where possible values of $Q$ are products of $Q_0$ and $p_{j_i,
  s_{j_i}}^{\gamma_i}$ or $p_{j_i, s_{j_i}}^{\gamma_i-1}$ for
$i\in\mathbb{N}_m$. Therefore, the proof of \eqref{eq:144} will be completed
if we show  that
\begin{align}
  \label{eq:148}
  \Big\|\Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i Qx\cdot
    w}\Big)\cdot Q^d\det(\mathcal E_N)\mathcal
  F^{-1}\eta\big(Q\mathcal E_N x\big)\Big\|_{\ell^1(x)}\le C_{\rho, r}
\end{align}
 for any integer $Q\le e^{N^{\rho}}$ such that
$(Q, q_{j, s})=1$, for all $j\in M^c$ and $s\in\mathbb{N}_{\beta_j}$. 

Recall that, according Remark \ref{rem:1}, in our case $\eta=\phi*\psi$ for some two smooth functions
$\phi, \psi$
supported in $(-1/(8d), 1/(8d))^d$.  Therefore, by the Cauchy--Schwarz inequality we only need to prove
that
\begin{align}
  \label{eq:22}
Q^{d/2}\det(\mathcal E_N)^{1/2}\big\|\mathcal
  F^{-1}\phi\big(Q\mathcal E_N x\big)\big\|_{\ell^2(x)}\le C_{\rho, r}  
\end{align}
and
\begin{align}
  \label{eq:15}
Q^{d/2}\det(\mathcal E_N)^{1/2}\Big\|\Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i Qx\cdot
    w}\Big)\cdot\mathcal
  F^{-1}\psi\big(Q\mathcal E_N x\big)\Big\|_{\ell^2(x)}\le C_{\rho, r}.
\end{align}
Since $(Q, q_{j, s})=1$, for all $j\in M^c$ and $s\in\mathbb{N}_{\beta_j}$
then $Qw\not\in \mathbb{Z}^d$ for any $w\in\mathcal U_{M^c}$  and its
denominator is bounded by $N^D$. We can assume, without of loss of
generality, that $Qw\in[0, 1)^d$ by the periodicity of  $x\mapsto e^{-2\pi i x\cdot
    Qw}$.
Inequality \eqref{eq:22} easily follows from Plancherel's theorem. In
order to prove \eqref{eq:15} observe that by the change of variables
one has
\begin{align*}
  \Big(\sum_{w\in\mathcal U_{M^c}}\alpha(w)e^{-2\pi i x\cdot
    Qw}\Big)\cdot\mathcal
  F^{-1}\psi\big(Q\mathcal E_N x\big)=Q^{-d}\det(\mathcal E_N)^{-1}
  \sum_{w\in\mathcal U_{M^c}}\alpha(w)\mathcal
  F^{-1}\big(\psi\big(Q^{-1}\mathcal E_N^{-1}(\: \cdot-Qw) \big)\big)(x).
\end{align*}
 Therefore, Plancherel's theorem and the last identity yield  
 \begin{multline}
